@Injectable()
export class AppErrorHandler implements ErrorHandler {
  private injector = inject(Injector);
  handleError(error: unknown): void {
    const monitoring = this.injector.get(Monitoring);
    monitoring.capture(error, { url: location.pathname });
    this.injector.get(Toasts).error('Coś poszło nie tak. Spróbuj ponownie.');
  }
}
